// ADR-2: stateless render token = base64(ts.nonce.HMAC_SHA256(secret, ts.nonce)).
// Requires NODE_FUNCTION_ALLOW_BUILTIN=crypto and WGC_HMAC_SECRET in the environment.
const crypto = require('crypto');
const secret = $env.WGC_HMAC_SECRET;
if (!secret) throw new Error('WGC_HMAC_SECRET is not set'); // fail loud, never issue unsigned tokens

// Gateway lock (2026-11-10). When WGC_GATEWAY_SECRET is set, only the
// wgcassetguide.com API gateway (/api/leads/*) may call this webhook. The
// gateway rate-limits per visitor, caps token reuse and guide emails, and
// derives the visitor IP from Cloudflare/Railway edge headers. n8n's
// allowedOrigins is only a CORS header and never stopped scripts. Unset =
// the old open behaviour, so setting the env var IS the cutover switch.
// Set it on BOTH the n8n main and worker services.
const GW = $env.WGC_GATEWAY_SECRET || '';
if (GW) {
  const got = Buffer.from(String(($json.headers || {})['x-wgc-gateway'] || ''), 'utf8');
  const exp = Buffer.from(GW, 'utf8');
  if (got.length !== exp.length || !crypto.timingSafeEqual(got, exp)) return [{ json: { token: '' } }];
}
const ts = String(Date.now());
const nonce = crypto.randomBytes(8).toString('hex');
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + nonce).digest('hex');
const token = Buffer.from(ts + '.' + nonce + '.' + mac, 'utf8').toString('base64');
return [{ json: { token } }];
